// CreateUploadSession: Open a direct multipart upload session for up to 50 files (POST /v1/assets/uploads).
//
// Returns, for each file, presigned S3 `UploadPart` URLs for its first (up to 100) parts. Upload the parts in
// parallel straight to S3 (PUT, each part `part_size` bytes except the last), keep the `ETag` of each answer,
// then call `complete`. The session lasts 24 hours. `Idempotency-Key` makes retries return the same session.
//
// Pass WithIdempotencyKey to make a retry safe.
func (s *AssetsService) CreateUploadSession(ctx context.Context, req *CreateUploadSessionRequest, opts ...RequestOption) (*UploadSession, error) {
	if req == nil {
		req = &CreateUploadSessionRequest{}
	}
	var body any = req
	var out UploadSession
	if err := s.c.do(ctx, requestSpec{method: http.MethodPost, path: "/v1/assets/uploads", query: nil, body: body}, &out, opts); err != nil {
		return nil, err
	}
	return &out, nil
}

