// GetEntitlement: Usage of one meter against the customer's limit (GET
// /v1/customers/{external_id}/entitlements/{meter}).
//
// Answered from near-real-time counters. They are eventually consistent (typically well under 2 s behind
// ingest): `as_of` is the ingest time of the newest event reflected in `used`. Payrudder never blocks ingest on
// a limit; call this before serving your customer and decide what to do. A customer without an entitlement on
// the meter is `unlimited`. `period` defaults to the current period in the tenant's time zone. A limit counts
// over its `window`: the billing month, or an hour, a day, an ISO week, a calendar year or the customer's whole
// lifetime, in the tenant's time zone. `period` picks the month of a monthly limit; every other window always
// reports its current one (`window_id`, ending at `resets_at`, which a lifetime window does not have).
// `allowed` follows the limit's `mode`: a `hard` limit stops allowing at the limit, a `soft` or `notify` one
// keeps allowing and says `over_limit`. Every window's counter is reconciled against the aggregator every few
// minutes, so an event delivered twice stops counting twice within one cycle.
func (s *CustomersService) GetEntitlement(ctx context.Context, externalID string, meter string, params *GetEntitlementParams, opts ...RequestOption) (*EntitlementStatus, error) {
	var out EntitlementStatus
	if err := s.c.do(ctx, requestSpec{method: http.MethodGet, path: "/v1/customers/" + url.PathEscape(externalID) + "/entitlements/" + url.PathEscape(meter), query: params.values(), body: nil}, &out, opts); err != nil {
		return nil, err
	}
	return &out, nil
}

