func (s *WebhookDeliveriesService) ListWebhookDeliveries(ctx context.Context, params *ListWebhookDeliveriesParams, opts ...RequestOption) (*ListWebhookDeliveriesResponse, error) {
	var out ListWebhookDeliveriesResponse
	if err := s.c.do(ctx, requestSpec{method: http.MethodGet, path: "/v1/webhook-deliveries", query: params.values(), body: nil}, &out, opts); err != nil {
		return nil, err
	}
	return &out, nil
}

// ListWebhookDeliveriesAll walks every page of ListWebhookDeliveries and yields the items one by one. It stops
// at the first error, which is yielded once.
func (s *WebhookDeliveriesService) ListWebhookDeliveriesAll(ctx context.Context, params *ListWebhookDeliveriesParams, opts ...RequestOption) iter.Seq2[WebhookDelivery, error] {
	return paginate(func(token string) ([]WebhookDelivery, string, error) {
		var p ListWebhookDeliveriesParams
		if params != nil {
			p = *params
		}
		p.PageToken = token
		page, err := s.ListWebhookDeliveries(ctx, &p, opts...)
		if err != nil {
			return nil, "", err
		}
		return page.Deliveries, page.NextPageToken, nil
	})
}

