// CreateWebhookEndpoint: Register an HTTPS endpoint that receives Payrudder's events (POST
// /v1/webhook-endpoints).
//
// Payrudder sends a signed JSON POST to the endpoint for each event of the types it asks for (all types if
// none). The response carries the signing secret, once; it cannot be read again, only rotated. Verify each
// delivery with the `Payrudder-Signature` header: `t=<unix seconds>,v1=<hex HMAC-SHA256 of "<t>.<raw body>"
// with the secret>` (two `v1` while a rotated secret is still accepted); reject a timestamp more than five
// minutes from your clock. Answer 2xx within 10 seconds; anything else is retried after 1 minute, 5 minutes, 30
// minutes, 2 hours, 6 hours and 24 hours, then given up (a delivery can be sent again by hand). Events are
// delivered at least once and not in order: use the event `id` to ignore repeats. The URL must be https and
// public; at most 20 endpoints.
func (s *WebhookEndpointsService) CreateWebhookEndpoint(ctx context.Context, req *CreateWebhookEndpointRequest, opts ...RequestOption) (*WebhookEndpoint, error) {
	if req == nil {
		req = &CreateWebhookEndpointRequest{}
	}
	var body any = req
	var out WebhookEndpoint
	if err := s.c.do(ctx, requestSpec{method: http.MethodPost, path: "/v1/webhook-endpoints", query: nil, body: body}, &out, opts); err != nil {
		return nil, err
	}
	return &out, nil
}

